<script lang="ts">
 import {onMount,untrack} from 'svelte';import {apiData} from '$lib/api';import {localization} from '$lib/localization';
 import RecordWidget from './RecordWidget.svelte';
 import DetailModal from '../DetailModal.svelte';import {runtimeConfiguration,widgetText,type WidgetInstance,type WidgetData} from '$lib/widgets';import WidgetContent from './WidgetContent.svelte';
 let content=$state<HTMLDivElement>();let shell=$state<HTMLDivElement>();let overflowing=$state(false),expanded=$state(false);let returnFocus=$state<HTMLElement|null>(null);
 function checkFit(){if(content&&shell)overflowing=content.scrollHeight>shell.clientHeight+1||content.scrollWidth>shell.clientWidth+1;}
 onMount(()=>{if(!shell||!content)return;const observer=new ResizeObserver(checkFit);observer.observe(shell);observer.observe(content);return()=>observer.disconnect();});
 let {instance,scale=1}:{instance:WidgetInstance;scale?:number}=$props();let t=$derived(widgetText[$localization.displayLanguage==='ja'?'ja':'en']);let data=$state<WidgetData|null>(null);let cardState=$state('loading');let busy=false;let controller:AbortController|undefined;
 async function load(force=false){
  if(busy&&!force)return;controller?.abort();const current=new AbortController();controller=current;busy=true;
  try{const response=await fetch(`/v1/employees/me/widget-instances/${instance.instanceKey}/data`,{cache:'no-store',signal:current.signal});if(!response.ok){const p=await response.json().catch(()=>null);if(current.signal.aborted)return;cardState=p?.error?.code==='WIDGET_STOPPED'?'stopped':response.status===403?'denied':'failed';data=null;return;}const result=await apiData<WidgetData>(response);if(current.signal.aborted)return;data=result;cardState='ready';}
  catch{if(!current.signal.aborted){cardState='failed';data=null;}}finally{if(controller===current)busy=false;}
 }
 $effect(()=>{instance;untrack(()=>void load(true));});
 onMount(()=>{const id=setInterval(()=>void load(),60000);return()=>{clearInterval(id);controller?.abort();};});
</script>
<div bind:this={shell} class="fit-shell"><div bind:this={content} class="fit-content" class:clock-only={instance.definition.view.length===1&&['runtime','clock','calculator','programmer_calculator','timer','stopwatch','unit_converter','personal_note','records'].includes(instance.definition.view[0].type)} class:overflowing inert={overflowing}>{#if cardState==='ready'&&data}{#if instance.definition.view.some(b=>b.type==='records')}<RecordWidget {instance}/>{:else}{#key instance.definition.runtime?`${instance.settings.custom?.[0]??''}:${instance.size}:${data.recordRevision??0}`:'declarative'}<WidgetContent instanceKey={instance.instanceKey} configuration={runtimeConfiguration(instance.definition,instance.settings)} {scale} definition={instance.definition} size={instance.size} note={data.note??''} clockDesign={instance.settings.clockDesign?.[0]??'digital'} {data}/>{/key}{/if}{:else}<p role="status">{cardState==='loading'?t.loading:cardState==='stopped'?t.stopped:cardState==='denied'?t.denied:t.failed}</p>{#if cardState!=='loading'}<button type="button" onclick={()=>{cardState='loading';void load();}}>{t.retry}</button>{/if}{/if}
</div>{#if overflowing}<div class="fit-notice"><p>{t.chooseLarger}</p><button type="button" onclick={event=>{returnFocus=event.currentTarget;expanded=true;}}>{t.more}</button></div>{/if}</div>
{#if expanded&&data}<DetailModal title={instance.definition.name[$localization.displayLanguage==='ja'?'ja':'en']} titleId="widget-overflow-detail" closeLabel={t.cancel} {returnFocus} onClose={()=>expanded=false}><WidgetContent instanceKey={instance.instanceKey} configuration={runtimeConfiguration(instance.definition,instance.settings)} definition={instance.definition} size={instance.size} note={data.note??''} clockDesign={instance.settings.clockDesign?.[0]??'digital'} {data} expandedView={true}/></DetailModal>{/if}
<style>.fit-shell{height:100%;min-height:0;position:relative}.fit-content{display:flow-root;width:100%}.fit-content.clock-only{height:100%}.fit-content.overflowing{position:absolute;top:0;left:0;visibility:hidden;pointer-events:none}.fit-notice{display:grid;align-content:start;gap:4px}.fit-notice p{margin:0;font-size:12px;line-height:1.3}p{color:var(--muted);line-height:1.6}button{border:1px solid var(--border);border-radius:6px;padding:8px 12px;background:var(--surface);color:var(--text);font:inherit;min-height:44px}</style>
